import pandas as pd
from pyspark.sql.functions import pandas_udf
from pyspark.sql.types import DoubleType

# Apache Arrow vectorized scalar UDF: batches Series -> Series
@pandas_udf(DoubleType())
def calculate_compound_interest(principal: pd.Series, rate: pd.Series, periods: pd.Series) -> pd.Series:
    # Runs vectorized in C via NumPy/Pandas inside Python worker
    return principal * ((1.0 + rate) ** periods)

